const blob=(c,f)=>execFileSync('git',['show',c+':'+f],{encoding:'utf8',maxBuffer:70e6});
const unitsAt=new Map();
function units(c,f){const key=c+':'+f;if(!unitsAt.has(key)){const text=blob(c,f);unitsAt.set(key,f.endsWith('.md')?extractMarkdownConservationUnits(text):[extractMixedFileConservationUnit(f,text)]);}return unitsAt.get(key);}
function prove(v,d){assert(v,'missing shown side');const c=v.contentCommit||head,f=v.path;const us=units(c,f),matches=us.filter(u=>u.textDigest===d);if(matches.length){if(v.anchor)assert(matches.some(u=>u.anchor===v.anchor)||matches.some(u=>u.text===v.text),'no native witness');return matches.find(u=>u.anchor===v.anchor)||matches[0];}assert.equal(hash(v.text),d,'shown text digest '+f);assert(blob(c,f).includes(v.text),'shown text absent '+f);return {anchor:v.anchor||'__file__',textDigest:d,ancestry:v.ancestry||[],text:v.text};}
const names=['261015-0027-root-pending-resume','261015-0027-root-truth-resume',...['01','02','03','04'].map(x=>'261015-0044-boundary-sync-resume-'+x)];
const docs=new Map(),get=f=>{if(!docs.has(f))docs.set(f,read(f));return docs.get(f);};
const nativeUnits=buildConservationUnitLookup(root,head),records=[],reworks=[],counts=[];
const registry=read(rr+'working-identity-registry.json'),identities=new Map(['units','identityGaps','retiredUnits'].flatMap(k=>registry[k]||[]).map(x=>[x.claimId,x]));
const preview=get(rr+'root-link-alias-preview-inputs-turn23.json'),sync=get(rr+'root-boundary-sync-accounting.json');
for(const name of names){
 const reportPath=rr+'review-'+name+'.md',text=blob(head,reportPath),pack=read(rr+'review-pack-'+name+'.md.json');
 const reviewer=text.match(/^Reviewer:\s*(.+)$/m)[1].trim(),table=new Map(text.split('\n').map(reviewTableCells).filter(c=>c.length===5&&['ok','rework','hold'].includes(c[1])).map(c=>[c[0],{claimId:c[0],verdict:c[1],note:c[2],sourceUnitDigest:c[3],targetUnitDigest:c[4]==='none'?null:c[4]}]));
 let oks=0,rws=0;
 for(const r of pack.rows){
  const reportID=r.kind==='native-identity-accounting'?r.id.replace('identity-claim_','native-identity-'):r.kind==='code-receipt-accounting'?(name.endsWith('-02')?r.id.replace('receipt-claim_','code-receipt-'):r.accounting.originalReviewedRef.claimId):r.kind==='changed-classification-accounting'?r.id.replace('classification-',''):r.id;
  const verdict=table.get(reportID);assert(verdict,'missing verdict '+reportID);assert.equal(verdict.sourceUnitDigest,r.sourceUnitDigest);assert.equal(verdict.targetUnitDigest,r.targetUnitDigest);
  const source=prove(r.source,verdict.sourceUnitDigest),target=verdict.targetUnitDigest?prove(r.target,verdict.targetUnitDigest):null;
  if(verdict.verdict!=='ok'){rws++;reworks.push({packID:r.id,reportID,reportPath,verdict});continue;}
  oks++;
  let row,shard,entryKind,destination;
  if(r.kind.startsWith('ordinary-')){entryKind=r.kind.slice('ordinary-'.length);shard=get(r.shard);row=shard[entryKind].find(x=>x.claimId===r.id);assert.deepEqual(row,r.decision,'decision changed '+r.id);destination={file:r.shard,entryKind,id:r.id};}
  else if(r.kind==='retired-registry-accounting'){row=sync.bindings.retiredAssignments.find(x=>x.claimId===r.id);assert.deepEqual(row,r.decision);shard={authorSession:row.authoredBy};destination={file:rr+'root-boundary-sync-accounting.json',entryKind:'bindings.retiredAssignments',id:r.id};}
  else {row={claimId:reportID,authoredBy:pack.authorSession,sourceUnitDigest:verdict.sourceUnitDigest,disposition:'supersede',reviewStatus:'pending',targetOwner:target?r.target.path:null,targetAnchor:target?'__shown__':null};shard={authorSession:pack.authorSession};destination={file:rr+'root-boundary-native-verification.json',entryKind:'fileEditsResume.accountingReviews',id:r.id};}
